"""Source-only finite four-SERVO rhs/impulse/residual budget, not sampled future bound."""
import sys,json,math
from pathlib import Path
import mpmath as mp
mp.iv.dps=45;iv=mp.iv
R=Path(__file__).resolve().parents[2];sys.path.insert(0,str(R/'tools'));from p9_model import write
E=json.load(open(R/'data/p13-20261026-theory/source-envelope-v1/envelope.json'));F=lambda x:iv.mpf(str(x));hi=lambda x:math.nextafter(float(x.b),math.inf);lo=lambda x:math.nextafter(float(x.a),-math.inf)
dt=F(1)/250;Ir=F('.00002649858234714004');deltaI=F('.000026115851691700804')-F('.00000038464910483993325');w=iv.sqrt(3)*8;O=F(1100);Imin=F(E['inertia_eigenvalue_lower_kgm2']);Imax=F(E['inertia_eigenvalue_upper_kgm2']);tau=F(E['external_torque_upper_Nm']);dI=4*deltaI*(O/10);spin=4*Ir*O/10
# Free rotor has no direct axial external motor torque in this source: thrust
# applied on rotor link, yaw/rolling moment applied to PARENT. Axial equation
# gives |qddot_free|<=|alpha_base_z|+deltaI/Ir*|wx wy|.
rotor_coriolis=deltaI/Ir*64;free_alpha=(tau+dI*w+Imax*w*w+spin*w+4*Ir*rotor_coriolis)/Imin
Ej=F(1);joint_now=(1000+Ej)/10;free_joint=joint_now+dt*(free_alpha+rotor_coriolis);command_joint=F(100);rhs=command_joint+free_joint;b2=2*rhs
root_yaw=F('.04000000000000001')+4*F('.016076923076923075')*2*F('.174')**2;kappa=1/root_yaw;alpha=1/Ir;c=F('1e-9');D=alpha+kappa;d=alpha+c*D;lam=b2/d;ideal_error=10*c*D*lam;eta_budget=Ej/10-c*D*lam
out=Path(sys.argv[1]);out.mkdir(parents=True,exist_ok=False);write(out/'budget.json',{'schema':'p13-finite-SERVO-budget-1','source_only_no_formal_fit':True,'working_domain':'predeclared bodyomega components8, filter<=1000, scaledjoint<=1100, Vrel<=12 source conditional domain. Current actual joint-filter/numeric discrepancy<=Ej1 is antecedent, not empirical max.','rotor_axial_coriolis_acceleration_bound_rad_s2':hi(rotor_coriolis),'free_body_angular_acceleration_upper_rad_s2':hi(free_alpha),'current_joint_abs_upper_rad_s':hi(joint_now),'free_joint_velocity_abs_upper_rad_s':hi(free_joint),'source_command_joint_abs_upper_rad_s':hi(command_joint),'rhs_component_abs_upper_rad_s':hi(rhs),'rhs_L2_upper_rad_s':hi(b2),'kappa_upper_inverse_inertia':hi(kappa),'A_condition_number_upper':hi((d+4*kappa)/d),'lambda_L2_upper_Nms':hi(lam),'real_exact_solver_CFM_scaled_joint_error_upper_rad_s':hi(ideal_error),'sufficient_eta_infinity_budget_for_scaled_joint_error1_rad_s':lo(eta_budget),'eta_unit':'servo-projected angular velocity rad/s; independently Aoriginal*lambda-b; never defined from ej','meaning':'conditional source recurrence closes bounded-rhs -> bounded impulse without finite force limit. The displayed eta budget is a concrete sufficient numeric condition for Ej1, NOT a proved actual future solver residual bound.','applicability':['four parallel-axis revolute SERVO rows with current prescribed commands, no clipping','no contact/other constraints; infinite force limits do not bound lambda','nominal source mass/inertia/geometry; numerical DeltaA treated separately','future actual floating solver residual <=displayed budget remains unproved','parent applied yaw/rolling moment, no direct rotor axial drive in force phase'],'first_remaining_numeric_obligation':'bound actual DART matrix perturbation and servo-projected eta on reachable finite mode domain, then close estimator/cache/history feedback','observed_old_solver_small_residual':'independent empirical support only, not used for constants','complete_closedloop_certificate':False})
print('FREE',hi(free_joint),'RHS',hi(rhs),'LAMBDA',hi(lam),'Ejideal',hi(ideal_error),'ETABUDGET',lo(eta_budget))
